package com.lanmessengerx.android

import android.content.Context
import org.json.JSONObject

/**
 * UI texts. The English text is the key; translations are loaded from assets/lang/<code>.json, the same files the
 * desktop client uses (generated by DesktopClient/tools/i18n/build_lang.py). Missing texts are shown in English.
 */
object Loc {
    /** The translations of the original LAN Messenger plus Hungarian, as offered in the settings. */
    val languages = listOf(
        "ar_SA" to "العربية", "bg_BG" to "Български", "de_DE" to "Deutsch", "en_US" to "English", "es_ES" to "Español",
        "fr_FR" to "Français", "hu_HU" to "Magyar", "it_IT" to "Italiano", "ja_JP" to "日本語", "ko_KR" to "한국어",
        "ml_IN" to "മലയാളം", "pl_PL" to "Polski", "pt_BR" to "Português (Brasil)", "ro_RO" to "Română", "ru_RU" to "Русский",
        "sk_SK" to "Slovenčina", "sl_SI" to "Slovenščina", "sv_SE" to "Svenska", "tr_TR" to "Türkçe",
    )

    private var map: Map<String, String> = emptyMap()
    var code: String = "en_US"
        private set

    /** [setting] is "system" or one of the codes in [languages]. */
    fun use(ctx: Context, setting: String) {
        code = if (setting == "system" || setting.isEmpty()) fromSystem(ctx) else setting
        map = try {
            val text = ctx.assets.open("lang/$code.json").bufferedReader(Charsets.UTF_8).use { it.readText() }
            val o = JSONObject(text)
            HashMap<String, String>(o.length() * 2).also { m -> o.keys().forEach { k -> m[k] = o.getString(k) } }
        } catch (_: Exception) {
            emptyMap()
        }
    }

    fun t(english: String): String = map[english]?.takeIf { it.isNotEmpty() } ?: english

    /** Translated text with {0}, {1} ... filled in. */
    fun f(english: String, vararg args: Any?): String {
        var s = t(english)
        args.forEachIndexed { i, a -> s = s.replace("{$i}", a.toString()) }
        return s
    }

    private fun fromSystem(ctx: Context): String {
        val l = ctx.resources.configuration.locales[0]
        val exact = "${l.language}_${l.country}"
        languages.firstOrNull { it.first.equals(exact, ignoreCase = true) }?.let { return it.first }
        return languages.firstOrNull { it.first.startsWith(l.language + "_", ignoreCase = true) }?.first ?: "en_US"
    }
}
